@Test
    void cantOrderMoreThanAvailableStock() {
        // given
        int customerId = 12;
        var quantities = Map.of(2, 3);

        // when
        assertThrows(IllegalArgumentException.class, () -> warehouse.addOrder(customerId, quantities));
    }

